WITH daily_returns AS ( SELECT i.i_manufact, wr.wr_returned_date_sk, SUM(wr.wr_net_loss) AS daily_net_loss, SUM(wr.wr_return_quantity) AS daily_return_qty, COUNT(DISTINCT wp.wp_web_page_id) AS distinct_pages FROM web_returns wr JOIN item i ON i.i_item_sk = wr.wr_item_sk LEFT JOIN web_page wp ON wp.wp_web_page_sk = wr.wr_web_page_sk GROUP BY i.i_manufact, wr.wr_returned_date_sk ), manufact_promo AS ( SELECT i.i_manufact, SUM(p.p_cost) AS total_promo_cost FROM promotion p JOIN item i ON i.i_item_sk = p.p_item_sk GROUP BY i.i_manufact ) SELECT dr.i_manufact, dr.wr_returned_date_sk, dr.daily_net_loss, dr.daily_return_qty, dr.distinct_pages, mp.total_promo_cost, SUM(dr.daily_net_loss) OVER (PARTITION BY dr.i_manufact ORDER BY dr.wr_returned_date_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_loss, AVG(dr.daily_net_loss) OVER (PARTITION BY dr.i_manufact ORDER BY dr.wr_returned_date_sk ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS rolling_7_day_avg_net_loss, CASE WHEN dr.daily_net_loss > 1000 THEN 'Very High Loss' WHEN dr.daily_net_loss BETWEEN 500 AND 1000 THEN 'High Loss' WHEN dr.daily_net_loss BETWEEN 200 AND 500 THEN 'Moderate Loss' ELSE 'Low Loss' END AS loss_severity FROM daily_returns dr LEFT JOIN manufact_promo mp ON mp.i_manufact = dr.i_manufact ORDER BY dr.i_manufact, dr.wr_returned_date_sk
